// Format Error Message for Email
const validation = $('Validate Data').first().json;
const aggregatedData = validation.aggregatedData;

// Get email from original input
const validateInput = $('Validate Input').first().json || $('Validate Input1').first().json;
const email = validateInput.email || 'admin@yourdomain.com';

return {
  toEmail: email,
  subject: `⚠️ SEO Report Generation Failed - ${aggregatedData.metadata?.targetUrl || 'Unknown'}`,
  errorType: 'Insufficient Data',
  message: validation.validationMessage,
  dataSourceCount: validation.dataSourceCount,
  totalSources: validation.totalSources,
  checks: {
