// Helper to check if a data source has subscription error
function hasSubscriptionError(dataSource) {
  if (!dataSource) return false;

  // ✅ FIX: Check for explicit status_code 40204
  if (dataSource.status_code === 40204) {
    return true;
  }

  // ✅ FIX: Check if success is 40204 (parse nodes set this when subscription error occurs)
  if (dataSource.success === 40204) {
    return true;
  }

  // ✅ FIX: Check for success: false with subscription error message
  if (dataSource.success === false) {
    const errorMsg = (dataSource.error || dataSource.message || '').toLowerCase();
    if (errorMsg.includes('subscription') || 
        errorMsg.includes('40204') ||
        errorMsg.includes('requires subscription activation')) {
      return true;
    }
  }

  return false;
}

