  },
  targetUrl: aggregatedData.metadata?.targetUrl || 'Unknown',
  reportType: aggregatedData.metadata?.reportType || 'unknown',
  timestamp: new Date().toISOString()
};

// Validate Data - Check if we have meaningful data (not all zeros/null/empty)
const input = $input.first().json;

// ✅ FIX: Extract aggregatedData - Handle both direct data and nested structure
const data = input.aggregatedData || input;

// Check OnPage - Look for ANY meaningful data
const hasOnPage = data.onPage?.success && (
  (data.onPage.onPage?.pagesCrawled > 0) ||
  (data.onPage.onPage?.issues?.critical > 0) ||
  (data.onPage.onPage?.issues?.warnings > 0) ||
  (data.onPage.onPage?.issues?.notices > 0) ||
  (data.onPage.onPage?.pageMetrics?.brokenLinks > 0) ||
  (data.onPage.onPage?.pageMetrics?.brokenResources > 0) ||
  (data.onPage.onPage?.pageMetrics?.duplicateTitle > 0) ||
  (data.onPage.onPage?.pageMetrics?.duplicateDescription > 0) ||
  (data.onPage.onPage?.pageMetrics?.duplicateContent > 0) ||
  (data.onPage.onPage?.performance?.avgPageLoadTime > 0) ||
  (data.onPage.onPage?.performance?.mobileUsability === true) ||
  (data.onPage.onPage?.crawlProgress && data.onPage.onPage.crawlProgress !== '')
);

// Check Domain Rank - Look for ANY meaningful data
const hasDomainRank = data.domainRank?.success && (
  (data.domainRank.domainRank?.totalKeywords > 0) ||
  (data.domainRank.domainRank?.estimatedTrafficValue > 0) ||
  (data.domainRank.domainRank?.estimatedPaidTrafficCost > 0) ||
  (data.domainRank.domainRank?.positions?.top3 > 0) ||
  (data.domainRank.domainRank?.positions?.top10 > 0) ||
  (data.domainRank.domainRank?.positions?.page2 > 0) ||
  (data.domainRank.domainRank?.positions?.page3 > 0) ||
  (data.domainRank.domainRank?.positions?.page4Plus > 0) ||
  (data.domainRank.domainRank?.movement?.newKeywords > 0) ||
  (data.domainRank.domainRank?.movement?.improved > 0) ||
  (data.domainRank.domainRank?.target && data.domainRank.domainRank.target !== '')
);

// Check Keywords - Look for ANY meaningful data
const hasKeywords = data.keywords?.success && (
  (data.keywords.keywords?.summary?.totalKeywords > 0) ||
  (data.keywords.keywords?.summary?.totalSearchVolume > 0) ||
  (data.keywords.keywords?.summary?.totalETV > 0) ||
  (data.keywords.keywords?.distribution?.top3Count > 0) ||
  (data.keywords.keywords?.distribution?.top10Count > 0) ||
  (data.keywords.keywords?.topPerformers?.length > 0) ||
  (data.keywords.keywords?.quickWinOpportunities?.length > 0) ||
  (data.keywords.keywords?.allKeywords?.length > 0)
);

// Check Backlinks - Look for ANY meaningful data
const hasBacklinks = data.backlinks?.success && (
  (data.backlinks.backlinks?.totalBacklinks > 0) ||
  (data.backlinks.backlinks?.referringDomains > 0) ||
  (data.backlinks.backlinks?.referringMainDomains > 0) ||
  (data.backlinks.backlinks?.dofollow > 0) ||
  (data.backlinks.backlinks?.nofollow > 0) ||
  (data.backlinks.backlinks?.rank > 0)
);

// Count valid data sources
const dataCount = [hasOnPage, hasDomainRank, hasKeywords, hasBacklinks].filter(Boolean).length;

// Require at least 2 out of 4 data sources to be valid
const hasValidData = dataCount >= 2;

return {
  hasValidData: hasValidData,
  dataCount: dataCount,
  totalSources: 4,
  checks: {
    onPage: hasOnPage,
    domainRank: hasDomainRank,
    keywords: hasKeywords,
    backlinks: hasBacklinks
  },
  aggregatedData: data,
  validationMessage: hasValidData 
    ? `Valid: ${dataCount}/4 data sources available`
    : `Invalid: Only ${dataCount}/4 data sources available (all zeros/null/empty)`
};

// Get metadata from Aggregate Data1 node
const aggregateData = $('Aggregate Data1').first().json;
const metadata = aggregateData.metadata || {};
const targetUrl = metadata.targetUrl || '';
const dateFrom = metadata.dateFrom || '';
const dateTo = metadata.dateTo || '';
const reportAudience = (metadata.reportAudience || 'client').toLowerCase();

const searchResult = $input.first().json;

// Handle different possible response shapes from Google Drive
const inputFiles = searchResult.files || searchResult.data?.files || [];

if (!targetUrl) {
  return [{
    json: {
      file: null,
      matched: false,
      error: 'No target URL found in metadata'
    }
  }];
}

// --- Create a slug that matches how filenames are generated ---

// 1) Base on the domain (no protocol, no path)
const domainOnly = targetUrl
  .replace(/^https?:\/\//, '')
  .replace(/^www\./, '')
  .split('/')[0]; // strip any path

// 2) Apply same cleaning as in Convert To Markdown1/2
const websiteSlug = domainOnly
  .replace(/[^a-zA-Z0-9]/g, '_')
  .replace(/_+/g, '_')
  .toLowerCase();

// Audience slug used in filenames: ..._client_ or ..._internal_
const audienceSlug = ['client', 'internal'].includes(reportAudience) ? reportAudience : 'client';

// Filter matching files (same site + same audience)
const matchedFiles = inputFiles.filter(file => {
  const name = (file.name || '').toLowerCase();

  const hasReport = name.includes('seo_performance_report');
  const hasUrl = name.includes(websiteSlug);
  const hasAudience = name.includes(`_${audienceSlug}_`);

  return hasReport && hasUrl && hasAudience;
});

if (matchedFiles.length === 0) {
  return [{
    json: {
      file: null,
      matched: false,
      debug: {
        targetUrl,
        websiteSlug,
        audienceSlug,
        totalFiles: inputFiles.length,
        sampleFilename: inputFiles[0]?.name
      }
    }
  }];
}

// Sort by modifiedTime descending (latest first)
matchedFiles.sort((a, b) => {
  const aTime = new Date(a.modifiedTime || a.createdTime || 0);
  const bTime = new Date(b.modifiedTime || b.createdTime || 0);
  return bTime - aTime;
});

return [{
  json: {
    file: matchedFiles[0],
    matched: true,
    totalMatches: matchedFiles.length,
    audienceSlug
  }
}];

// Json Data File - Progress Report Workflow
// Place this node AFTER "Convert To Markdown1" node
// It will work for both paths (with and without previous report)

// Get all data from Aggregate Data1 node
const aggregateData = $('Aggregate Data1').first().json;

// Get data from Validate Input1 for metadata
const validateInput = $('Validate Input1').first().json;

// Get markdown conversion data (try both paths)
const markdown1 = $('Convert To Markdown1').first()?.json;
const markdownData = markdown1;

// Combine all data into a single JSON object
const combinedData = {
  metadata: {
    generatedAt: new Date().toISOString(),
    reportType: validateInput.report_type || 'progress',
    reportAudience: validateInput.report_audience || 'client',
    targetUrl: validateInput.target_url || 'unknown',
    location: validateInput.location || 'United Kingdom',
    dateFrom: validateInput.date_from || null,
    dateTo: validateInput.date_to || null
  },
  aggregatedData: aggregateData
};

// Convert to formatted JSON string
const jsonString = JSON.stringify(combinedData, null, 2);

// Get target website for filename
const targetWebsite = markdownData?.targetWebsite || 
                      validateInput.target_url || 
                      'website';
const cleanWebsite = targetWebsite.replace(/[^a-zA-Z0-9]/g, '_').replace(/_+/g, '_');
const date = new Date().toISOString().split('T')[0];
const dateFrom = validateInput.date_from || '';
const dateTo = validateInput.date_to || '';
const dateRange = dateFrom && dateTo ? `_${dateFrom}_to_${dateTo}` : '';
const filename = `SEO_Data_${cleanWebsite}${dateRange}_${date}.json`;

// Convert to base64 for binary (required for Google Drive)
const base64Content = Buffer.from(jsonString, 'utf8').toString('base64');

return {
  json: {
    filename: filename,
    targetWebsite: targetWebsite,
    generatedAt: date,
    dateFrom: dateFrom,
    dateTo: dateTo,
    jsonContent: jsonString
  },
  binary: {
    data: {
      data: base64Content,
      mimeType: 'application/json',
      fileName: filename,
      fileExtension: 'json'
    }
  }
};

